{
  "title": "The Mirror Rescue of Atheria",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "Massive iron gates twisted open, overgrown with thorny vines. The glass diver stands before them, his diving helmet reflecting the shattered stained-glass windows of nearby buildings.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer studies a map by a cracked fountain.",
      "visual_description": "A cracked marble fountain in a cobblestone square. Mara kneels, unrolling a parchment map weighted with her brass compass, ink-stained fingers tracing a route toward the central tower.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning from a lamppost.",
      "visual_description": "A bent iron lamppost with the Oracle Lamp hanging from it, its single flame-eye glowing amber. It casts a long shadow across ruined stalls and scattered royal banners.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver peers into a cursed tower's mirrored surface.",
      "visual_description": "A tall, spiraling tower covered in reflective black glass. The glass diver places his hand against it, and ripples spread across the surface like water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara notes a hidden passage behind a collapsed wall.",
      "visual_description": "A pile of rubble and broken stone near a wall painted with faded royal crests. Mara brushes dust off a low archway, compass needle spinning.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The Sleeping Tax Collector snores on a pile of ledgers.",
      "visual_description": "Inside a roofless guardhouse, the Sleeping Tax Collector lies on a mound of soggy ledgers, papers stuck to his sleeves, a quill tucked behind his ear.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The Tin Fox scurries ahead through a narrow alley.",
      "visual_description": "A dark alley cluttered with broken carts and torn banners. The Tin Fox picks its way over debris, its key-wind tail ticking softly, blue eyes scanning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The Oracle Lamp reveals a trap in the main square.",
      "visual_description": "A wide square with a collapsed fountain and a cracked sundial. The Oracle Lamp's flame-eye flares, casting a sharp shadow that points to a tripwire hidden in the dust.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through a mirror into a locked room.",
      "visual_description": "Inside a sealed chamber, a tall mirror on the wall ripples. The glass diver steps out of it, water dripping from his coat, a rusted iron door before him.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara marks a safe route past a crumbling bell tower.",
      "visual_description": "A leaning bell tower with loose stones and a cracked bell. Mara draws a swift line on her map, glancing up as dust trickles down.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The Sleeping Tax Collector wakes briefly to stamp a permit.",
      "visual_description": "A desk made from a fallen door. The Sleeping Tax Collector, still half-asleep, stamps a soggy paper and hands it to the Tin Fox, then resumes snoring.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp warns of a patrol near the old barracks.",
      "visual_description": "A long, shadowy street with the barracks' iron gates ahead. The Oracle Lamp swings, its flame shrinking to a whisper, dimming its light.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver uses a window to bypass a locked gate.",
      "visual_description": "A rusted portcullis blocking a tunnel. The glass diver touches a small window, his reflection dissolving into the glass, reappearing on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara finds a secret door disguised as a royal tapestry.",
      "visual_description": "A torn tapestry showing a faded coat of arms. Mara pulls it aside to reveal a stone door with no handle, only a compass-shaped indentation.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The Tin Fox disarms a pressure plate under loose cobbles.",
      "visual_description": "A section of cobblestone street that dips slightly. The Tin Fox pries up a stone with its metal teeth, revealing a pressure plate, then carefully disconnects it with its tail key.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The Oracle Lamp illuminates the path to the escape bridge.",
      "visual_description": "A dark tunnel opening onto a view of a stone bridge over a dry moat. The Oracle Lamp blazes bright, its flame dancing to show a clear path.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver carries the Sleeping Tax Collector to safety.",
      "visual_description": "The glass diver, with the Sleeping Tax Collector slung over his shoulder, steps out of a shattered window onto the bridge. The Tax Collector clutches his ledger pillow.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The group assembles on the bridge as the city crumbles behind them.",
      "visual_description": "A stone bridge with missing balustrades. Mara checks her map, the Tin Fox sits at her feet, the Oracle Lamp hangs from her belt, and the glass diver stands with the Tax Collector. The ruined city glows orange in the distance.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

